async function api(path,options={}){const headers=new Headers(options.headers||{});const stamp=options.knowledgeRevision??knowledgeRevision;if(stamp&&options.method&&options.method!=='GET'&&path.startsWith('/knowledge/'))headers.set('If-Match',stamp);const response=await fetch(path,{...options,headers});const revision=response.headers.get('X-Knowledge-Revision');if(revision)knowledgeRevision=revision;let data;try{data=await response.json()}catch{throw Error('Máy chủ chưa trả về kết quả. Vui lòng thử lại.')}if(!response.ok){if(Array.isArray(data.detail))throw Error('Có trường bị trống, quá dài hoặc sai định dạng. Vui lòng kiểm tra lại.');throw Error(viError(data.detail||''))}return data}
const post=(path,body,stamp=knowledgeRevision)=>api(path,{method:'POST',knowledgeRevision:stamp,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
async function showLayout(kind,trigger){
  if(!layoutPromise)layoutPromise=api('/layouts').catch(error=>{layoutPromise=null;throw error});
  const layouts=await layoutPromise,spec=layouts[kind];if(!spec)return;
  const columns=spec.columns,examples={IDKH:'001234',TENKH:'Nguyễn Văn A',NOIDUNG:'TT tien nuoc MA KH 001234',NGAY:'02/07/2026 08:15',GHICO:'150000',GHINO:'',SOTIEN:'150000',NGANHANG:'VCB',REFERENCE:'FT2618300123'};
  const main=columns.filter(column=>column.optional_group!=='payment'),extra=columns.filter(column=>column.optional_group==='payment');
  layoutReturnFocus=trigger||document.activeElement;$('layoutTitle').textContent=spec.title;
  $('layoutBody').innerHTML='<div class="sheetpreview"><table><thead><tr>'+main.map(column=>'<th'+(column.required?' class="req"':'')+'>'+esc(column.key)+'</th>').join('')+'</tr></thead><tbody><tr>'+main.map(column=>'<td>'+esc(examples[column.key]||'')+'</td>').join('')+'</tr></tbody></table></div><dl class="layoutcols">'+main.map(column=>'<dt'+(column.required?' class="req"':'')+'>'+esc(column.key)+'</dt><dd>'+esc(column.description)+'</dd>').join('')+'</dl>'+(extra.length?'<details><summary>Cột thu hộ (tùy chọn)</summary><dl class="layoutcols">'+extra.map(column=>'<dt>'+esc(column.key)+'</dt><dd>'+esc(column.description)+'</dd>').join('')+'</dl></details>':'');
  $('layoutModal').classList.remove('hidden');$('layoutClose').focus();
}
function closeLayout(){$('layoutModal').classList.add('hidden');if(layoutReturnFocus?.isConnected)layoutReturnFocus.focus()}
function transferDateText(value){if(!value)return 'Chưa có ngày giờ';const match=String(value).match(/^(\d{4})-(\d{2})-(\d{2})(?:T|\s)?(.*)$/);return match?match[3]+'/'+match[2]+'/'+match[1]+(match[4]?' '+match[4]:''):String(value)}
function paymentPeriodSummary(row){return '<div class="reviewfacts"><div><span>Kỳ thanh toán</span><strong>'+esc(row.payment_period||'Chưa xác định')+'</strong></div><div><span>Ngày chuyển khoản</span><strong>'+esc(transferDateText(row.date))+'</strong></div><div><span>Số tiền</span><strong>'+esc(row.amount!=null?Number(row.amount).toLocaleString('vi-VN')+' ₫':'—')+'</strong></div></div>'}

function matchScoreText(row){if(row.status==='confirmed')return 'Đã xác nhận';if(row.evidence?.unknown_customer)return 'Chưa có lịch sử';if(!row.score&&row.candidate_group?.total)return 'Chỉ có nhóm gợi ý';return pct(row.score)}
function candidateGroupNote(row){return row.status==='pending'&&row.candidate_group?.total?'<div class="casenote suggest">Nhóm gợi ý: '+Number(row.candidate_group.total).toLocaleString('vi-VN')+' khách hàng</div>':''}
function canBulkConfirm(row){return row.status==='pending'&&row.decision==='auto_accept'&&Boolean(row.customer_id)&&!row.evidence?.multiple_customer_ids}
function recommendationSummary(row){
  const items=row.recommendations||[],group=row.evidence?.batch_settlement?.related_customers||[];
  if(!items.length&&!group.length)return '';
  return '<details class="innerdetails"><summary>'+(group.length?'Khách hàng từng được phân bổ':'Khách hàng gợi ý')+'</summary><div class="tablewrap"><table><thead><tr><th>IDKH</th><th>Khách hàng</th><th></th></tr></thead><tbody>'+(items.length?items:group).map(item=>'<tr><td>'+esc(item.customer_id)+'</td><td>'+esc(item.customer_name)+(item.sources?.length?'<div class="rowmeta">'+item.sources.map(esc).join('; ')+'</div>':'')+'</td><td><div class="buttons">'+'<button type="button" class="small" data-candidate-evidence="'+esc(item.customer_id)+'">Xem mẫu</button>'+(items.length&&row.status==='pending'?'<button type="button" class="small" data-use-customer="'+esc(item.customer_id)+'">Chọn</button>':'')+'</div></td></tr>').join('')+'</tbody></table></div></details>';
}
function entityNameComparison(evidence){
  const comparison=evidence.name_entity_comparison||evidence.nearest_history?.name_entity_comparison;
  if(!comparison)return '';
  const status={match:'Tên đầy đủ trùng khớp',mismatch:'Tên đầy đủ khác nhau',missing:'Chưa đủ tên để đối chiếu'};
  return '<div class="innerdetails"><b>'+esc(status[comparison.status]||'Đối chiếu tên')+'</b><div class="tablewrap"><table><thead><tr><th>Tên trong giao dịch</th><th>Tên trong mẫu đã học</th></tr></thead><tbody><tr><td>'+esc((comparison.query_names||[]).join('; ')||'Chưa trích được tên')+'</td><td>'+esc((comparison.history_names||[]).join('; ')||'Chưa trích được tên')+'</td></tr></tbody></table></div></div>';
}
function nameExtractionSummary(row){const names=row.extracted_names||[];return names.length?'<div class="innerdetails"><label>Tên trong nội dung</label><b>'+names.map(esc).join('; ')+'</b></div>':''}

async function action(button,work){if(button){pendingActions.add(button);button.disabled=true;button.setAttribute('aria-busy','true')}try{return await work()}catch(error){toast(error.message,true)}finally{if(button){pendingActions.delete(button);button.removeAttribute('aria-busy');button.disabled=(button.classList.contains('needs-db')&&!dbReady)||button.dataset.stopping==='true'}}}
function askConfirmation(title,text,label='Xác nhận'){if(confirmResolver)return Promise.resolve(false);confirmReturnFocus=document.activeElement;$('confirmTitle').textContent=title;$('confirmText').textContent=text;$('confirmAccept').textContent=label;$('confirmModal').classList.remove('hidden');$('confirmCancel').focus();return new Promise(resolve=>{confirmResolver=resolve})}
function finishConfirmation(answer){const resolve=confirmResolver;confirmResolver=null;$('confirmModal').classList.add('hidden');if(confirmReturnFocus?.isConnected)confirmReturnFocus.focus();resolve?.(answer)}
function selectTab(id){for(const button of document.querySelectorAll('[data-tab]')){const active=button.dataset.tab===id;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;$(button.dataset.tab).classList.toggle('hidden',!active)}document.body.dataset.page=id;$('pageTitle').textContent=pageInfo[id];$('breadcrumb').textContent=pageInfo[id];if(id==='database'&&dbReady)loadDatabaseTables().catch(error=>toast(error.message,true));if(id==='tasks')jobs().catch(error=>toast(error.message,true))}
function updateSelection(){for(const id of [...selectedIds]){const row=rows.get(id);if(row&&!canBulkConfirm(row))selectedIds.delete(id)}$('bulkBar').classList.toggle('hidden',selectedIds.size===0);$('bulkCount').textContent=selectedIds.size+' giao dịch đã chọn';const eligible=[...rows.values()].filter(row=>canBulkConfirm(row));$('selectAll').disabled=!eligible.length;$('selectAll').checked=eligible.length>0&&eligible.every(row=>selectedIds.has(row.id));$('selectAll').indeterminate=eligible.some(row=>selectedIds.has(row.id))&&!$('selectAll').checked}
function showResults(){syncResultFilters();viewCleared=false;resultRequestId++;offset=0;selectedIds.clear();$('pendingCount').classList.remove('hidden');updateSelection()}
function clearResults(){viewCleared=true;resultRequestId++;offset=0;total=0;rows.clear();selectedIds.clear();selected=null;$('modalBg').classList.add('hidden');$('transactionRows').innerHTML='<tr><td colspan="7" class="empty">Chưa có kết quả hiển thị.</td></tr>';$('pageInfo').textContent='0 giao dịch';$('prevButton').disabled=true;$('nextButton').disabled=true;$('pendingCount').classList.add('hidden');updateSelection()}
async function stats(){if(!dbReady)return;const requestId=++statsRequestId,jobId=activeJob;const p=activeJob?'?job_id='+encodeURIComponent(activeJob):'';const data=await api('/stats'+p);if(requestId!==statsRequestId||jobId!==activeJob)return;lastStats=data;$('customerCount').textContent=data.customers.toLocaleString('vi-VN');$('patternCount').textContent=data.patterns.toLocaleString('vi-VN');$('pendingCount').textContent=data.pending_review.toLocaleString('vi-VN')+' chưa duyệt';$('fileTotal').textContent=data.transactions.toLocaleString('vi-VN');$('filePending').textContent=data.pending_review.toLocaleString('vi-VN');$('fileConfirmed').textContent=data.confirmed.toLocaleString('vi-VN');$('learningNotice').classList.toggle('hidden',!data.pending_learning);$('learningNoticeText').textContent=data.pending_learning+' xác nhận đang chờ lưu vào dữ liệu.'}
async function loadRows(){if(!dbReady||viewCleared)return;const requestId=++resultRequestId;if(!activeJob){rows.clear();$('transactionRows').innerHTML='<tr><td colspan="7" class="empty">Chưa có kết quả đối soát.</td></tr>';$('pageInfo').textContent='0 giao dịch';$('prevButton').disabled=true;$('nextButton').disabled=true;updateSelection();return}const p=new URLSearchParams({offset,limit:20,job_id:activeJob,q:$('resultQuery').value.trim()});if($('decisionFilter').value)p.set('decision',$('decisionFilter').value);if($('statusFilter').value)p.set('status',$('statusFilter').value);const result=await api('/transactions?'+p);if(viewCleared||requestId!==resultRequestId)return;if(result.total&&offset>=result.total){offset=Math.floor((result.total-1)/20)*20;return loadRows()}total=result.total;rows=new Map(result.items.map(row=>[row.id,row]));$('transactionRows').innerHTML=result.items.length?result.items.map(row=>'<tr><td class="selectcell">'+(canBulkConfirm(row)?'<input type="checkbox" data-select-row="'+row.id+'" aria-label="Chọn giao dịch '+row.id+'" '+(selectedIds.has(row.id)?'checked':'')+'>':'')+'</td><td class="raw"><div class="rawline">'+esc(row.raw)+'</div><div class="rowmeta">'+(row.sheet?'Sheet '+esc(row.sheet)+' · ':'')+(row.row_index?'Dòng '+row.row_index:'Nhập trực tiếp')+' · '+'Chuyển khoản: '+esc(transferDateText(row.date))+(row.amount?' · '+row.amount.toLocaleString('vi-VN')+' ₫':'')+'</div></td><td class="paymentperiod"><span class="periodlabel">Kỳ thanh toán</span><b>'+esc(row.payment_period||'Chưa xác định')+'</b></td><td><b>'+esc(row.confirmed_customer_name||row.customer_name||row.suggested_customer_name||'Chưa xác định')+'</b><div class="rowmeta">'+esc(row.confirmed_customer_id||row.customer_id||row.suggested_customer_id||'')+'</div>'+(row.extracted_names?.length?'<div class="rowmeta">Tên trong nội dung: '+row.extracted_names.map(esc).join('; ')+'</div>':'')+caseNote(row)+candidateGroupNote(row)+'</td><td><b>'+esc(matchScoreText(row))+'</b></td><td><span class="pill '+esc(row.status==='pending'?row.decision:row.status)+'">'+esc(row.status==='pending'?decisions[row.decision]:statuses[row.status])+'</span></td><td><button class="small" data-review="'+row.id+'">Kiểm tra</button></td></tr>').join(''):'<tr><td colspan="7" class="empty">Không có giao dịch phù hợp với bộ lọc.</td></tr>';$('pageInfo').textContent=total?`${offset+1}–${Math.min(offset+20,total)} / ${total.toLocaleString('vi-VN')} giao dịch`:'0 giao dịch';$('prevButton').disabled=offset===0;$('nextButton').disabled=offset+20>=total;updateSelection()}
async function refresh(){await Promise.all([stats(),loadRows()])}
function identifierEvidence(evidence){const owners=evidence.confirmed_identifier_owners;if(!owners||!Object.keys(owners).length)return '';const labels={'id':'Mã khách hàng','contract':'Hợp đồng','bound-id':'Số đã xác nhận','code':'Mã chữ/số'};return '<details class="innerdetails"><summary>Định danh trong lịch sử</summary><div class="tablewrap"><table><thead><tr><th>Loại</th><th>Mã / số</th><th>Khách hàng đã xác nhận</th></tr></thead><tbody>'+Object.entries(owners).map(([token,ids])=>{const split=token.indexOf(':');return '<tr><td>'+esc(labels[token.slice(0,split)]||'Định danh')+'</td><td>'+esc(token.slice(split+1))+'</td><td>'+ids.map(esc).join(', ')+'</td></tr>'}).join('')+'</tbody></table></div></details>'}
function orderedEvidence(history){const comparison=history.numeric_comparison;if(!comparison)return '';return '<div class="tablewrap"><table><thead><tr><th>Vị trí</th><th>Hiện tại</th><th>Lịch sử</th><th>Loại số</th><th>Đối chiếu</th></tr></thead><tbody>'+comparison.ordered_comparison.map(row=>'<tr><td>'+esc(row.slot)+(row.history_slot!=null&&row.history_slot!==row.slot?' → '+esc(row.history_slot):'')+'</td><td>'+esc(row.query_value)+'</td><td>'+esc(row.history_value??'—')+'</td><td>'+esc(numericTypes[row.type]||row.type)+'</td><td>'+(!row.same_role?'Khác vai trò':row.exact?'Trùng đầy đủ':row.variable_reference?'Tham chiếu thay đổi':'Khác giá trị')+'</td></tr>').join('')+'</tbody></table></div><p class="hint">Mẫu nội dung '+(comparison.template_compatible?'tương thích':'khác cấu trúc')+'; hợp đồng '+(comparison.contract_conflict?'khác nhau':comparison.aligned_contracts.length?'khớp chính xác':'chưa có bằng chứng khớp')+'.</p>'+(history.customer_id_priority_over_contract?'<p class="hint">Ưu tiên IDKH đã khớp; HD có thể dùng cho nhiều IDKH.</p>':'')+(comparison.code_alignment_complete===false?'<p class="hint">Chưa đối chiếu được mã chữ/số hoặc số cơ sở theo đúng thứ tự. Hiện tại: '+esc((comparison.query_codes||[]).map(code=>code[1]).join(', ')||'Không có')+'. Lịch sử: '+esc((comparison.history_codes||[]).map(code=>code[1]).join(', ')||'Không có')+'.</p>':'')}
function customerAutocomplete(id,optionsId,nameId){let timer,version=0;$(id).oninput=()=>{const requestId=++version;clearTimeout(timer);if(nameId)$(nameId).value='';timer=setTimeout(async()=>{try{const value=$(id)?.value||'',items=await api('/customers?q='+encodeURIComponent(value));if(requestId!==version||!$(optionsId))return;$(optionsId).innerHTML=items.map(item=>'<option value="'+esc(item.id)+'">'+esc(item.name)+' · '+item.pattern_count+' mẫu</option>').join('');const exact=items.find(item=>item.id===value);if(exact&&nameId&&$(nameId))$(nameId).value=exact.name}catch{}},230)}}
function caseNote(row){const e=row.evidence||{};if(row.status!=='pending')return'';if(e.batch_settlement)return'<div class="casenote batch">Thu hộ tổng hợp · '+esc(e.batch_settlement.provider_name||'đơn vị thu hộ')+' — đối chiếu bảng kê</div>';if((e.allocation_customer_ids||[]).length)return'<div class="casenote multi">Nhiều khách hàng: '+e.allocation_customer_ids.map(esc).join(', ')+((e.unknown_allocation_ids||[]).length?' · chưa có: '+e.unknown_allocation_ids.map(esc).join(', '):'')+'</div>';if((e.history_allocation_customer_ids||[]).length)return'<div class="casenote multi">Lịch sử chia cho: '+e.history_allocation_customer_ids.map(esc).join(', ')+'</div>';if(row.suggested_customer_id)return'<div class="casenote suggest">Mã đề xuất: '+esc(row.suggested_customer_id)+(e.suggested_customer_name?' – '+esc(e.suggested_customer_name):'')+'</div>';return''}
function showReview(row){
  if(!row)return;
  selected=row;reviewReturnFocus=document.activeElement;
  const evidence=row.evidence||{},history=(evidence.matched_pattern||evidence.shared_collection_match)?evidence:evidence.nearest_history||{};
  const detected=row.normalization?.customer_ids||[],allocation=evidence.allocation_customer_ids||[];
  const suggested=row.suggested_customer_id||(evidence.multiple_customer_ids?detected.join(', '):'')||row.customer_id||(allocation.length>1?allocation.join(', '):'')||(!evidence.recurring_group&&detected.length===1&&detected[0].length<=100?detected[0]:'');
  const pending=row.status==='pending';
  $('reviewTitle').textContent=pending?'Duyệt giao dịch':'Chi tiết giao dịch';
  const form=pending?'<form id="reviewForm" class="reviewform"><h3>Khách hàng thanh toán</h3><div class="fieldrow"><div><label for="correctId">Mã khách hàng</label><input id="correctId" maxlength="2000" required value="'+esc(suggested)+'" placeholder="Nhập mã khách hàng" list="customerOptions"><datalist id="customerOptions"></datalist></div><div><label for="correctName">Tên khách hàng</label><input id="correctName" maxlength="300" value="'+esc(evidence.multiple_customer_ids?'':(suggested===row.customer_id?row.customer_name:row.suggested_customer_name)||'')+'"></div></div>'+(row.extracted_name?'<button id="useExtractedName" class="small" type="button">Dùng tên: '+esc(row.extracted_name)+'</button>':'')+'<details class="innerdetails"><summary>Kiểu thanh toán · '+esc(paymentLabels[row.payment_mode]||paymentLabels.unknown)+'</summary>'+paymentFields('reviewPayment',row,true)+'</details></form>':'<div class="reviewfacts"><div><span>Khách hàng đã xác nhận</span><strong>'+esc(row.confirmed_customer_name||row.customer_name||'—')+'</strong><span>'+esc(row.confirmed_customer_id||row.customer_id||'')+'</span></div></div>';
  const explanation='<details class="innerdetails" id="matchDetails"><summary>Căn cứ đối chiếu</summary><p>'+esc(evidence.reason_vi||'Chưa đủ thông tin để xác định khách hàng.')+'</p><label>'+esc(history.shared_collection_match?'Mẫu thu hộ dùng chung':'Mẫu trong lịch sử')+'</label><div class="rawfull">'+esc(history.matched_pattern||history.shared_template||'Chưa có mẫu phù hợp.')+'</div>'+(history.pattern_source?'<p class="hint">'+esc(history.pattern_source.file||'')+(history.pattern_source.row?' · Dòng '+esc(history.pattern_source.row):'')+'</p>':'')+paymentModeSummary(row)+nameExtractionSummary(row)+entityNameComparison(evidence)+sharedTemplateSummary(history)+identifierEvidence(evidence.confirmed_identifier_owners?evidence:history)+(history.numeric_comparison?'<details id="numberDetails" class="innerdetails"><summary>Đối chiếu số theo đúng thứ tự</summary>'+orderedEvidence(history)+'</details>':'')+(history.matched_template?'<details id="templateDetails"><summary>Nội dung & cấu trúc</summary><label>Mẫu trong lịch sử</label><pre>'+esc(history.matched_template)+'</pre><label>Mẫu giao dịch hiện tại</label><pre>'+esc(history.query_template||row.normalization?.template||'')+'</pre>'+(history.match_steps_vi?'<ol>'+history.match_steps_vi.map(step=>'<li>'+esc(step)+'</li>').join('')+'</ol>':'')+'</details>':'')+'</details>';
  $('reviewBody').innerHTML='<div class="reviewstatus"><span class="pill '+esc(pending?row.decision:row.status)+'">'+esc(pending?decisions[row.decision]:statuses[row.status])+'</span><span class="sub">'+esc(matchScoreText(row))+'</span>'+caseNote(row)+'</div>'+paymentPeriodSummary(row)+'<label>Nội dung chuyển khoản</label><div class="rawfull reviewraw">'+esc(row.raw)+'</div>'+form+recommendationSummary(row)+candidateGroupSummary(row)+explanation+(pending?'<div class="reviewactions"><button id="rejectReview" class="danger" type="button">Không ghép</button><button id="acceptReview" class="primary" type="submit" form="reviewForm">Xác nhận & học</button></div>':'');
  $('modalBg').classList.remove('hidden');$('closeModal').focus();
  if(pending){
    $('reviewForm').onsubmit=event=>{event.preventDefault();action(event.submitter,()=>feedback(true))};
    $('rejectReview').onclick=()=>action($('rejectReview'),()=>feedback(false));
    customerAutocomplete('correctId','customerOptions','correctName');
    for(const button of $('reviewBody').querySelectorAll('[data-use-customer]'))button.onclick=()=>{
      const item=(row.recommendations||[]).find(item=>item.customer_id===button.dataset.useCustomer);
      if(item){$('correctId').value=item.customer_id;$('correctName').value=item.customer_name||'';$('correctId').focus()}
    };
    if($('useExtractedName'))$('useExtractedName').onclick=()=>{$('correctName').value=row.extracted_name};
  }
  bindCandidateGroup(row);
}
function closeReview(){
  $('modalBg').classList.add('hidden');
  if(reviewReturnFocus?.isConnected)reviewReturnFocus.focus();
}
function syncResultFilters(){
  for(const button of document.querySelectorAll('[data-status-shortcut]'))button.setAttribute('aria-pressed',String(button.dataset.statusShortcut===$('statusFilter').value));
}

async function feedback(accept){const row=selected;if(!row)return;const id=accept?$('correctId').value.trim():null;if(accept&&!id)throw Error('Nhập hoặc chọn mã khách hàng trước khi xác nhận.');await post('/feedback',{transaction_id:row.id,accepted:accept,correct_customer_id:id,customer_name:accept?$('correctName').value.trim():'',...(accept?paymentData('reviewPayment'):{})});$('modalBg').classList.add('hidden');selectedIds.delete(row.id);toast(accept?'Đã xác nhận và bổ sung vào kiến thức.':'Đã ghi nhận từ chối ghép khách hàng này.');await refresh()}
function setExportLinks(){for(const [id,suffix] of [['resultXlsx','/results.xlsx'],['resultCsv','/csv.zip']]){const element=$(id);element.classList.toggle('disabled',!activeJob);if(activeJob)element.href='/export/'+encodeURIComponent(activeJob)+suffix;else element.removeAttribute('href')}}
function updateSelectOptions(select,markup,selectedValue){
  let state=selectUpdates.get(select);
  if(!state){
    state={markup:null,pending:null};selectUpdates.set(select,state);
    select.addEventListener('blur',()=>queueMicrotask(()=>{
      const update=state.pending;
      if(update)updateSelectOptions(select,update.markup,update.selectedValue);
    }));
  }
  // Native dropdowns close if their options are replaced while the user is choosing.
  if(document.activeElement===select){state.pending={markup,selectedValue};return}
  state.pending=null;
  const value=selectedValue();
  if(state.markup!==markup){select.innerHTML=markup;state.markup=markup}
  if(select.value!==value)select.value=value;
}
function syncJobNodes(parent,fresh){
  const keyOf=node=>node.nodeType===1?node.getAttribute('data-job-key'):null;
  const existing=[...parent.childNodes],keyed=new Map(existing.filter(keyOf).map(node=>[keyOf(node),node])),retained=new Set();
  const sources=[...fresh.childNodes],nextKeys=new Set(sources.map(keyOf).filter(Boolean));
  // Remove expired sections first so remaining focused elements need not be moved.
  for(const [key,node] of keyed)if(!nextKeys.has(key))node.remove();
  let cursor=parent.firstChild;
  for(const source of sources){
    const key=keyOf(source);
    let node=key?keyed.get(key):cursor;
    if(node&&(node.nodeType!==source.nodeType||node.nodeName!==source.nodeName||keyOf(node)!==key))node=null;
    if(!node){node=source.cloneNode(true);parent.insertBefore(node,cursor)}
    else{
      if(node!==cursor)parent.insertBefore(node,cursor);
      if(node.nodeType===1){
        // Keep the existing details/summary elements and the user's open/closed state.
        const preserve=name=>node.tagName==='DETAILS'&&name==='open'||name==='disabled'&&pendingActions.has(node);
        for(const attribute of [...node.attributes])if(!preserve(attribute.name)&&!source.hasAttribute(attribute.name))node.removeAttribute(attribute.name);
        for(const attribute of source.attributes)if(!preserve(attribute.name)&&node.getAttribute(attribute.name)!==attribute.value)node.setAttribute(attribute.name,attribute.value);
        syncJobNodes(node,source);
      }else if(node.nodeValue!==source.nodeValue)node.nodeValue=source.nodeValue;
    }
    retained.add(node);cursor=node.nextSibling;
  }
  for(const node of existing)if(!retained.has(node))node.remove();
}
function renderJobs(markup){
  const fresh=document.createElement('template');fresh.innerHTML=markup;
  syncJobNodes($('jobs'),fresh.content);
}
function jobStage(job){
  if(job.status!=='running')return '';
  const summary=job.summary||{};
  if(summary.phase==='reading')return '<p class="hint" data-job-key="stage">Đang đọc tệp giao dịch…</p>';
  if(summary.phase==='classifying')return '<p class="hint" data-job-key="stage">Đang đối soát sheet <b>'+esc(summary.current_sheet)+'</b>'+(summary.current_row?' · Dòng '+esc(summary.current_row):'')+'.</p>';
  return '';
}
function sheetSummary(job){
  const counts=job.summary?.sheet_counts||{},skipped=job.summary?.skipped_sheets||[],kind=job.kind==='knowledge_import'?'confirmed':'raw';
  const reasons={confirmed_layout:'dữ liệu đã gán nhãn, dùng mục Nhập dữ liệu',raw_layout:'sheet ngân hàng chưa gán nhãn, dùng mục Đối soát',unsupported_layout:'không nhận diện được bố cục giao dịch',ambiguous_layout:'có nhiều cột cùng vai trò, cần làm rõ tiêu đề'};
  
  const corrections=skipped.some(item=>['unsupported_layout','ambiguous_layout'].includes(item.reason));
  return (Object.keys(counts).length?'<details data-job-key="sheets"><summary>Giao dịch theo sheet</summary>'+Object.entries(counts).map(([name,count])=>'<div class="hint" data-job-key="sheet:'+esc(name)+'">'+esc(name)+' · '+(Number(count)?Number(count).toLocaleString('vi-VN')+' dòng':'Chưa có kết quả')+'</div>').join('')+'</details>':'')+
    (skipped.length?'<details data-job-key="skipped" open><summary>'+skipped.length+' sheet được bỏ qua</summary>'+skipped.map(item=>'<div class="hint" data-job-key="sheet:'+esc(item.sheet)+'"><b>'+esc(item.sheet)+'</b> · '+esc(reasons[item.reason]||item.reason)+'</div>').join('')+(corrections?'<p class="hint" data-job-key="layout"><a href="#layoutModal" data-layout="'+kind+'">mẫu bố cục</a>.</p>':'')+'</details>':'');
}
function rowErrorSummary(job){
  const count=job.summary?.row_error_count||0;
  if(!count)return '';
  const samples=(job.summary.row_errors||[]).slice(0,20),stages={read:'Đọc dữ liệu',prepare:'Chuẩn bị nội dung',learn:'Học kiến thức',classify:'Đối soát'};
  return '<details data-job-key="row-errors"><summary>'+Number(count).toLocaleString('vi-VN')+' dòng lỗi đã bỏ qua</summary><p class="hint" data-job-key="explanation">Các dòng còn lại tiếp tục được xử lý. Sửa các dòng lỗi trong tệp nguồn rồi nhập lại khi cần.</p><div class="tablewrap" data-job-key="table"><table><thead><tr><th>Sheet</th><th>Dòng trong tệp</th><th>Bước xử lý</th><th>Nguyên nhân</th></tr></thead><tbody>'+samples.map(issue=>'<tr><td>'+esc(issue.sheet)+'</td><td>'+esc(issue.row_index??('Không xác định · vị trí XML '+(issue.row_position??'—')))+'</td><td>'+esc(stages[issue.stage]||issue.stage)+'</td><td>'+esc(viError(issue.error))+'</td></tr>').join('')+'</tbody></table></div>'+(count>samples.length?'<p class="hint" data-job-key="more">Hiển thị '+samples.length+' dòng đầu. CSV chứa toàn bộ danh sách lỗi.</p>':'')+'<div class="buttons" data-job-key="actions"><a class="button small" href="/jobs/'+encodeURIComponent(job.id)+'/errors.csv">Tải danh sách dòng lỗi CSV</a></div></details>';
}
function jobMarkup(job){
  const running=['queued','running','cancelling'].includes(job.status),file=job.kind==='batch_classify';
  return '<div class="job" data-job-key="job:'+esc(job.id)+'"><div class="jobtop" data-job-key="header"><div><b>'+esc(job.filename||kinds[job.kind]||'Tác vụ')+'</b><div class="rowmeta">'+esc(kinds[job.kind]||'Xử lý')+' · '+esc(job.created_at?.slice(0,16).replace('T',' ')||'')+'</div></div><span class="pill '+esc(job.status)+'">'+esc(statuses[job.status]||job.status)+(job.status==='completed'&&job.summary?.row_error_count?' · có dòng lỗi':'')+'</span></div>'+
    (running?'<div class="jobprogress" data-job-key="progress"><span></span></div>':'')+
    '<div class="hint" data-job-key="count">Đã xử lý '+job.progress.toLocaleString('vi-VN')+' dòng'+(job.summary?.counts?.learned!=null?' · '+job.summary.counts.learned+' dòng được học':'')+'</div>'+jobStage(job)+sheetSummary(job)+rowErrorSummary(job)+
    (job.error?'<div class="joberror" data-job-key="error">'+esc(viError(job.error))+'</div>':'')+
    '<div class="buttons" data-job-key="actions">'+
    (running?'<button class="small danger" data-job-key="stop" data-stop-job="'+esc(job.id)+'" data-stopping="'+String(job.status==='cancelling')+'" '+(job.status==='cancelling'?'disabled':'')+'>Dừng xử lý</button>':'')+
    (file&&job.progress?'<button class="small" data-job-key="view" data-view-job="'+esc(job.id)+'">Xem kết quả</button><a class="button small" data-job-key="xlsx" href="/export/'+esc(job.id)+'/results.xlsx">Tải Excel</a><a class="button small" data-job-key="csv" href="/export/'+esc(job.id)+'/csv.zip">CSV theo sheet (ZIP)</a>':'')+
    (!running?'<button class="small danger" data-job-key="delete" data-delete-job="'+esc(job.id)+'">Xóa tệp làm việc</button>':'')+'</div></div>';
}
async function jobs(){
  const requestId=++jobsRequestId,items=(await api('/jobs')).filter(job=>job.kind!=='benchmark');
  // A slower response must not overwrite a newer refresh or a stop/delete result.
  if(requestId!==jobsRequestId)return true;
  jobItems=items;
  const imports=jobItems.find(job=>job.kind==='knowledge_import'&&['queued','running','cancelling'].includes(job.status));
  activeImportId=imports?.id||null;
  $('stopImportButton').classList.toggle('hidden',!imports);
  $('stopImportButton').dataset.stopping=String(imports?.status==='cancelling');
  $('stopImportButton').disabled=pendingActions.has($('stopImportButton'))||imports?.status==='cancelling';
  const stopLabel=imports?.status==='cancelling'?'Đang dừng…':'Dừng nhập';
  if($('stopImportButton').textContent!==stopLabel)$('stopImportButton').textContent=stopLabel;
  const files=jobItems.filter(job=>job.kind==='batch_classify'),previous=activeJob;
  if(!files.some(job=>job.id===activeJob))activeJob=files[0]?.id||null;
  const options=files.length?files.map(job=>'<option value="'+esc(job.id)+'">'+esc(job.filename||'Tệp ngân hàng')+' · '+esc(statuses[job.status])+' · '+job.progress+' dòng</option>').join(''):'<option value="">Chưa có tệp làm việc</option>';
  updateSelectOptions($('jobFilter'),options,()=>activeJob||'');
  if(previous!==activeJob&&!viewCleared){offset=0;resultRequestId++;selectedIds.clear()}
  setExportLinks();
  const active=jobItems.filter(job=>['queued','running','cancelling'].includes(job.status));
  $('taskCount').classList.toggle('hidden',!active.length);$('taskCount').textContent=active.length;
  renderJobs(jobItems.length?jobItems.map(jobMarkup).join(''):'<div class="empty">Chưa có tệp làm việc. Tải tệp để bắt đầu.</div>');
  return active.length>0;
}
async function stopJob(id){if(!id)return;const result=await post('/jobs/'+encodeURIComponent(id)+'/cancel',{});toast(result.status==='cancelling'?'Đang dừng xử lý. Phần đã hoàn tất được giữ.':result.status==='cancelled'?'Đã dừng tác vụ.':'Tác vụ đã kết thúc.');await jobs();if(dbReady)await refresh()}
async function pollJobs(){if(polling)return;polling=true;try{let active=true;while(active){active=await jobs();if(dbReady)await refresh();if(active)await new Promise(resolve=>setTimeout(resolve,2000))}}catch(error){toast(error.message,true)}finally{polling=false}}
async function queued(result,classifying=false){if(classifying){activeJob=result.job_id;showResults();selectTab('workspace')}else selectTab('tasks');await jobs();toast(classifying?'Đã bắt đầu đối soát.':'Đã bắt đầu nhập dữ liệu.');if(dbReady)await refresh();pollJobs()}
const tableLabels={recurring_links:'Nội dung đã xác nhận',bank_aliases:'Tên ngân hàng / ví',knowledge_changes:'Nhật ký chỉnh kiến thức',customers:'Khách hàng',customer_id_slots:'Vị trí IDKH đã học',customer_aliases:'Tên khác của khách hàng',payer_entities:'Người / tài khoản trả tiền',collection_memberships:'Khách hàng thu hộ',payment_templates:'Mẫu giao dịch',transaction_patterns:'Mẫu của khách hàng',numeric_features:'Giá trị số đã học',numeric_slots:'Vị trí số trong mẫu',retrieval_postings:'Khóa tìm kiếm',knowledge_receipts:'Dấu xác nhận đã học',knowledge_metadata:'Thông tin kho kiến thức',hard_negatives:'Ghép sai đã bị từ chối'};
