const previewColumns={recurring_links:['id','customer_id','channel_key','raw_example','seen_count'],bank_aliases:['id','alias','channel_key','note'],knowledge_changes:['id','actor','action','entity_key','created_at'],customer_aliases:['id','customer_id','alias','confidence'],collection_memberships:['id','template_id','customer_id','seen_count','last_seen'],customers:['id','canonical_name','pattern_count','collection_count'],payment_templates:['id','display_name','payment_mode','template_text','customer_count'],transaction_patterns:['id','customer_id','template_id','payment_mode','raw_example'],payer_entities:['id','customer_id','payer_name','payer_type','seen_count'],numeric_features:['id','pattern_id','numeric_value','numeric_type','slot_index']};
function databaseMeta(){return databaseTables.find(table=>table.name===$('databaseTable').value)}
function fieldLabel(name){return columnLabels[name]||name}
const knowledgeActionLabels={'customer.create':'Thêm khách hàng','customer.rename':'Sửa tên khách hàng','customer.delete':'Xóa khách hàng','pattern.create':'Thêm mẫu đã duyệt','pattern.correct':'Sửa liên kết mẫu','pattern.delete':'Xóa liên kết mẫu','pattern.payment':'Sửa kiểu thanh toán của liên kết','template.describe':'Sửa thông tin mẫu','template.payment':'Sửa kiểu thanh toán của mẫu','template.payment.bulk':'Sửa kiểu thanh toán hàng loạt','template.delete':'Xóa mẫu','collection.delete':'Xóa liên kết thu hộ','alias.create':'Thêm bí danh khách hàng','alias.confirm':'Xác nhận bí danh','alias.delete':'Xóa bí danh','bank_alias.create':'Thêm bí danh ngân hàng / ví','negative.delete':'Gỡ chặn cách ghép','change.undo':'Hoàn tác thay đổi','import.start':'Bắt đầu nhập dữ liệu đã duyệt','import.confirmed':'Hoàn tất nhập kiến thức','import.cancelled':'Dừng nhập kiến thức','feedback.confirm':'Xác nhận khách hàng thanh toán','feedback.reject':'Từ chối cách ghép'};
function fieldText(name,value){if(value==null)return '—';if(name==='action')return knowledgeActionLabels[value]||String(value);if(typeof value==='object')return JSON.stringify(value,null,2);if(name==='payment_mode')return paymentLabels[value]||value;if(name==='provider_kind')return providerLabels[value]||value;if(name==='numeric_type')return numericTypes[value]||value;if(name==='payer_type')return {bank:'Ngân hàng / kênh trả tiền',account:'Tài khoản / thẻ'}[value]||value;if(typeof value==='boolean')return value?'Có':'Không';return String(value)}
async function loadDatabaseTables(){if(!dbReady)return;const requestId=++databaseTableRequestId,tables=await api('/database/tables');if(requestId!==databaseTableRequestId)return;const previous=$('databaseTable').value;databaseTables=tables;const main=['customers','payment_templates','collection_memberships','transaction_patterns','recurring_links','payer_entities','customer_aliases','bank_aliases','knowledge_changes','numeric_features'],groups=[['Hồ sơ & mẫu đã học',main],['Dữ liệu hỗ trợ',tables.map(table=>table.name).filter(name=>!main.includes(name))]];$('databaseTable').innerHTML=groups.map(([label,names])=>'<optgroup label="'+esc(label)+'">'+names.map(name=>{const table=tables.find(item=>item.name===name);return table?'<option value="'+esc(name)+'">'+esc(tableLabels[name]||name)+' · '+table.count.toLocaleString('vi-VN')+' bản ghi</option>':''}).join('')+'</optgroup>').join('');$('databaseTable').value=tables.some(table=>table.name===previous)?previous:'customers';await loadDatabaseRows()}
async function loadDatabaseRows(){
  const meta=databaseMeta();if(!dbReady||!meta)return;
  $('databaseHeading').textContent=tableLabels[meta.name]||'Dữ liệu';for(const button of document.querySelectorAll('[data-table-shortcut]'))button.setAttribute('aria-pressed',String(button.dataset.tableShortcut===meta.name));$('databaseAddCustomer').classList.toggle('primary',meta.name==='customers');$('databaseAddPattern').classList.toggle('primary',meta.name!=='customers');
  const requestId=++databaseRequestId,currentOffset=databaseOffset,hasMode=['payment_templates','transaction_patterns'].includes(meta.name);
  const scope={q:$('databaseQuery').value.trim(),filter_payment_mode:hasMode?$('databasePaymentMode').value||null:null};
  const p=new URLSearchParams({offset:currentOffset,limit:20,q:scope.q});
  if(databaseCustomerScope)p.set('customer_id',databaseCustomerScope);if(databaseTemplateScope)p.set('template_id',databaseTemplateScope);if(scope.filter_payment_mode)p.set('payment_mode',scope.filter_payment_mode);
  databaseBulkScope=null;$('databaseBulkPayment').disabled=true;$('databaseBulkPayment').textContent='Đổi kiểu thanh toán';
  $('databasePaymentControls').classList.toggle('hidden',!hasMode);$('databaseBulkPayment').classList.toggle('hidden',meta.name!=='payment_templates');
  $('databasePrev').disabled=true;$('databaseNext').disabled=true;$('databaseHeaders').innerHTML='';$('databaseRows').innerHTML='<tr><td colspan="6" class="empty">Đang tải dữ liệu…</td></tr>';
  const result=await api('/database/tables/'+encodeURIComponent(meta.name)+'/rows?'+p);if(requestId!==databaseRequestId)return;
  if(result.total&&currentOffset>=result.total){databaseOffset=Math.floor((result.total-1)/20)*20;return loadDatabaseRows()}
  const columns=previewColumns[meta.name]||meta.columns.slice(0,5).map(column=>column.name);
  $('databaseHeaders').innerHTML='<tr>'+columns.map(name=>'<th>'+esc(fieldLabel(name))+'</th>').join('')+'<th></th></tr>';
  $('databaseRows').innerHTML=result.items.length?result.items.map(row=>'<tr>'+columns.map(name=>{const text=fieldText(name,row[name]);return '<td class="dbcell"><div class="rawline">'+esc(text.length>180?text.slice(0,180)+'…':text)+'</div></td>'}).join('')+'<td class="dbactions"><button class="small" data-database-row="'+esc(row[meta.primary_key])+'">Chi tiết</button></td></tr>').join(''):'<tr><td colspan="'+(columns.length+1)+'" class="empty">Không có dữ liệu phù hợp.</td></tr>';
  $('databasePageInfo').textContent=result.total?`${currentOffset+1}–${Math.min(currentOffset+20,result.total)} / ${result.total.toLocaleString('vi-VN')} bản ghi`:'0 bản ghi';
  $('databasePrev').disabled=currentOffset===0;$('databaseNext').disabled=currentOffset+20>=result.total;
  $('databaseHint').textContent=['customers','transaction_patterns','payment_templates','collection_memberships','customer_aliases','bank_aliases','knowledge_changes','hard_negatives'].includes(meta.name)?'':'Chỉ xem';
  $('databaseScope').classList.toggle('hidden',!databaseCustomerScope&&!databaseTemplateScope);$('databaseScopeText').textContent=databaseCustomerScope?'Các mẫu của khách hàng '+databaseCustomerScope:databaseTemplateScope?'Các liên kết của mẫu giao dịch '+databaseTemplateScope:'';
  if(meta.name==='payment_templates'&&result.total&&scope.q===$('databaseQuery').value.trim()&&scope.filter_payment_mode===($('databasePaymentMode').value||null)){
    databaseBulkScope={...scope,expected_count:result.total,expected_links:result.link_total,scope_digest:result.scope_digest};$('databaseBulkPayment').disabled=false;$('databaseBulkPayment').textContent='Đổi kiểu thanh toán · '+result.total.toLocaleString('vi-VN')+' mẫu';
  }
}
function openBulkTemplatePayment(){
  if(!databaseBulkScope||databaseMeta()?.name!=='payment_templates')return;
  const scope={...databaseBulkScope};if(scope.q!==$('databaseQuery').value.trim()||scope.filter_payment_mode!==($('databasePaymentMode').value||null))return;
  databaseSelected=null;databaseReturnFocus=document.activeElement;$('databaseRecordTitle').textContent='Cập nhật kiểu thanh toán hàng loạt';
  $('databaseRecordBody').innerHTML='<p><b>'+scope.expected_count.toLocaleString('vi-VN')+' mẫu · '+scope.expected_links.toLocaleString('vi-VN')+' liên kết khách hàng</b> · tất cả các trang.</p><p class="hint">Tìm kiếm: '+esc(scope.q||'Tất cả')+' · Kiểu hiện tại: '+esc(scope.filter_payment_mode?paymentLabels[scope.filter_payment_mode]:'Tất cả')+'</p><form id="bulkTemplatePaymentForm">'+paymentFields('bulkTemplatePayment',{},false,true)+'<label class="check"><input type="checkbox" required><span>Tôi xác nhận cập nhật toàn bộ mẫu và liên kết trên.</span></label><button class="primary" type="submit">Xác nhận & cập nhật tất cả</button></form>';
  $('databaseModal').classList.remove('hidden');$('bulkTemplatePaymentMode').focus();
  $('bulkTemplatePaymentForm').onsubmit=event=>{event.preventDefault();action(event.submitter,async()=>{
    const result=await post('/knowledge/templates/payment/bulk',{...scope,...paymentData('bulkTemplatePayment'),confirmed:true});closeDatabaseRecord();toast('Đã cập nhật '+result.updated_templates+' mẫu và '+result.updated_links+' liên kết.');await loadDatabaseTables();
  })};
}

function closeDatabaseRecord(){databaseSelected=null;$('databaseModal').classList.add('hidden');if(databaseReturnFocus?.isConnected)databaseReturnFocus.focus()}
function sharedTemplateEditor(row){return '<div class="buttons"><span class="pill">'+esc(row.customer_count||0)+' khách hàng · '+esc(row.link_count||0)+' liên kết</span><button id="databaseTemplateLinks" class="small">Xem mẫu của khách hàng</button>'+(row.collection_customer_count?'<button id="databaseCollectionLinks" class="small">Khách hàng thu hộ ('+esc(row.collection_customer_count)+')</button>':'')+'</div><label>Bố cục mẫu giao dịch</label><pre class="dbvalue">'+esc(row.template_text)+'</pre><form id="databaseEditForm"><label for="sharedTemplateName">Tên quản lý mẫu</label><input id="sharedTemplateName" maxlength="300" value="'+esc(row.display_name||'')+'"><label for="sharedTemplateDescription">Ghi chú</label><textarea id="sharedTemplateDescription" maxlength="4000" rows="3">'+esc(row.description||'')+'</textarea><button class="primary" type="submit">Lưu thông tin mẫu giao dịch</button></form><details class="innerdetails" open><summary>Đánh dấu thu hộ / tự trả cho mẫu</summary><form id="templatePaymentForm">'+paymentFields('templatePayment',row)+'<label class="check"><input type="checkbox" required><span>Áp dụng cho '+esc(row.link_count||0)+' liên kết hiện có và các liên kết mới chưa có nhãn riêng.</span></label><button class="primary" type="submit">Lưu loại của mẫu & áp dụng</button></form></details>'}
function linkPaymentEditor(row){return '<div class="divider"></div><div class="buttons"><span class="pill">Mẫu giao dịch '+esc(row.template_id)+'</span><button id="databaseSharedTemplate" class="small">Xem mẫu giao dịch</button></div><form id="linkPaymentForm"><h3>Kiểu thanh toán của liên kết này</h3>'+paymentFields('linkPayment',row)+'<button class="primary" type="submit">Lưu kiểu thanh toán</button></form>'}
function templatePatternScope(templateId){closeDatabaseRecord();$('databaseTable').value='transaction_patterns';$('databaseQuery').value='';$('databasePaymentMode').value='';databaseCustomerScope=null;databaseTemplateScope=templateId;databaseOffset=0;loadDatabaseRows().catch(error=>toast(error.message,true))}
function bindTemplateEditors(meta,row){if($('databaseCollectionLinks'))$('databaseCollectionLinks').onclick=()=>{closeDatabaseRecord();databaseCustomerScope=null;databaseTemplateScope=row.id;databaseOffset=0;$('databaseTable').value='collection_memberships';$('databaseQuery').value='';$('databasePaymentMode').value='';loadDatabaseRows().catch(error=>toast(error.message,true))};
  if($('databaseTemplateLinks'))$('databaseTemplateLinks').onclick=()=>templatePatternScope(row.id);
  if($('databaseSharedTemplate'))$('databaseSharedTemplate').onclick=()=>action($('databaseSharedTemplate'),async()=>{const templateMeta=databaseTables.find(table=>table.name==='payment_templates');if(!templateMeta)return;const template=await api('/database/tables/payment_templates/rows/'+encodeURIComponent(row.template_id));showDatabaseRecord(templateMeta,template)});
  for(const [form,prefix,path] of [['templatePaymentForm','templatePayment','/knowledge/templates/'],['linkPaymentForm','linkPayment','/knowledge/patterns/']])if($(form))$(form).onsubmit=event=>{event.preventDefault();action(event.submitter,async()=>{const result=await api(path+encodeURIComponent(row.id)+'/payment',{method:'PATCH',knowledgeRevision:row._revision,headers:{'Content-Type':'application/json'},body:JSON.stringify(paymentData(prefix))});closeDatabaseRecord();toast(form==='templatePaymentForm'?'Đã lưu loại của mẫu và cập nhật '+result.updated_links+' liên kết.':'Đã cập nhật kiểu thanh toán của liên kết.');await loadDatabaseTables()})};
}
function databaseDeletion(meta,row){if(!['customers','transaction_patterns','payment_templates','collection_memberships'].includes(meta.name)||meta.name==='payment_templates'&&row.link_count)return '';const label=meta.name==='customers'?'khách hàng và kiến thức liên quan':meta.name==='payment_templates'?'mẫu giao dịch chưa có liên kết':'liên kết mẫu của khách hàng';const message=meta.name==='customers'?'Xóa hồ sơ khách hàng cùng các mẫu, số và thông tin trả tiền đã học của khách hàng này.':meta.name==='payment_templates'?'Chỉ xóa bố cục mẫu giao dịch chưa được khách hàng nào sử dụng.':meta.name==='collection_memberships'?'Xóa khách hàng này khỏi danh sách thu hộ của mẫu. Hồ sơ khách hàng và các mẫu khác được giữ.':'Xóa liên kết cùng các số và khóa tìm kiếm riêng. Mẫu giao dịch và liên kết của các khách hàng khác được giữ.';return '<details class="dbconfirm"><summary>Xóa '+label+'</summary><p>'+message+'</p><p class="hint">Tệp làm việc và CSV đã tải không bị thay đổi.</p><label class="check"><input id="databaseDeleteConfirm" type="checkbox"><span>Tôi xác nhận xóa kiến thức này.</span></label><button id="databaseDelete" class="danger" disabled>Xóa '+label+'</button></details>'}
function customerPatternScope(customerId){closeDatabaseRecord();$('databaseTable').value='transaction_patterns';$('databaseQuery').value='';$('databasePaymentMode').value='';databaseCustomerScope=customerId;databaseTemplateScope=null;databaseOffset=0;loadDatabaseRows().catch(error=>toast(error.message,true))}
function showDatabaseRecord(meta,row,trigger){databaseSelected={table:meta.name,key:String(row[meta.primary_key]),row};databaseReturnFocus=trigger||document.activeElement;$('databaseRecordTitle').textContent=(tableLabels[meta.name]||'Dữ liệu kiến thức')+' · '+String(row[meta.primary_key]);let edit='';if(meta.name==='customers')edit='<div class="buttons"><span class="pill">'+(row.pattern_count||0)+' mẫu đã học</span><button id="databaseCustomerPatterns" class="small">Xem mẫu đã học</button><button id="databaseCustomerCollections" class="small">Xem mẫu thu hộ</button><button id="databaseCustomerAddPattern" class="primary small">Thêm mẫu cho khách hàng này</button></div><form id="databaseEditForm"><div class="divider"></div><label for="databaseEditName">Tên khách hàng</label><input id="databaseEditName" maxlength="300" required value="'+esc(row.canonical_name)+'"><label class="check"><input type="checkbox" required><span>Tôi xác nhận tên khách hàng đã sửa.</span></label><button class="primary" type="submit">Lưu tên khách hàng</button></form>';
if(meta.name==='transaction_patterns')edit='<form id="databaseEditForm"><label for="databaseEditCustomer">Mã khách hàng của mẫu</label><input id="databaseEditCustomer" maxlength="100" required value="'+esc(row.customer_id)+'" list="databaseCustomerOptions"><datalist id="databaseCustomerOptions"></datalist><label for="databaseEditRaw" class="evidence-title">Nội dung giao dịch mẫu</label><textarea id="databaseEditRaw" maxlength="32767" rows="6" required>'+esc(row.raw_example)+'</textarea><label class="check"><input type="checkbox" required><span>Tôi đã kiểm tra nội dung và khách hàng của mẫu.</span></label><div class="buttons"><button class="primary" type="submit">Lưu mẫu đã sửa</button><button id="databaseVariantPattern" type="button">Thêm một mẫu khác</button></div></form>';
if(meta.name==='payment_templates')edit=sharedTemplateEditor(row);if(meta.name==='transaction_patterns')edit+=linkPaymentEditor(row);const numeric=meta.name==='transaction_patterns'?(row.segments||[]).filter(segment=>segment.type==='number'):[],numbers=numeric.length?'<details><summary>Các số đã học</summary>'+numeric.map(number=>'<div class="dbvalue"><b>Vị trí '+esc(number.slot)+' · '+esc(numericTypes[number.numeric_type]||number.numeric_type)+'</b><div>'+esc(number.value)+'</div></div>').join('')+'</details>':'';const fields=meta.columns.map(column=>'<label>'+esc(fieldLabel(column.name))+'</label><pre class="dbvalue">'+esc(fieldText(column.name,row[column.name]))+'</pre>').join('');const deletion=databaseDeletion(meta,row);$('databaseRecordBody').innerHTML=edit+numbers+'<details'+(!edit?' open':'')+'><summary>Dữ liệu lưu trữ</summary>'+fields+'</details>'+deletion;$('databaseModal').classList.remove('hidden');$('databaseClose').focus();if($('databaseEditForm'))$('databaseEditForm').onsubmit=event=>{event.preventDefault();action(event.submitter,saveDatabaseRecord)};if($('databaseEditCustomer'))customerAutocomplete('databaseEditCustomer','databaseCustomerOptions');if($('databaseCustomerPatterns'))$('databaseCustomerPatterns').onclick=()=>customerPatternScope(row.id);if($('databaseCustomerCollections'))$('databaseCustomerCollections').onclick=()=>{closeDatabaseRecord();$('databaseTable').value='collection_memberships';$('databaseQuery').value='';$('databasePaymentMode').value='';databaseCustomerScope=row.id;databaseTemplateScope=null;databaseOffset=0;loadDatabaseRows().catch(error=>toast(error.message,true))};if($('databaseCustomerAddPattern'))$('databaseCustomerAddPattern').onclick=()=>action($('databaseCustomerAddPattern'),()=>openCreatePattern(row.id));if($('databaseVariantPattern'))$('databaseVariantPattern').onclick=()=>action($('databaseVariantPattern'),()=>openCreatePattern(row.customer_id));bindTemplateEditors(meta,row);if(typeof bindInteractiveEditors==='function')bindInteractiveEditors(meta,row);if($('databaseDeleteConfirm')){$('databaseDeleteConfirm').onchange=()=>$('databaseDelete').disabled=!$('databaseDeleteConfirm').checked;$('databaseDelete').onclick=()=>action($('databaseDelete'),deleteDatabaseRecord)}}
async function saveDatabaseRecord(){const selection=databaseSelected;if(!selection)return;if(selection.table==='payment_templates'){await api('/knowledge/templates/'+encodeURIComponent(selection.key),{method:'PATCH',knowledgeRevision:selection.row._revision,headers:{'Content-Type':'application/json'},body:JSON.stringify({display_name:$('sharedTemplateName').value.trim(),description:$('sharedTemplateDescription').value.trim()})});closeDatabaseRecord();toast('Đã cập nhật mẫu giao dịch.');await loadDatabaseTables();return}const customer=selection.table==='customers',body=customer?{name:$('databaseEditName').value.trim()}:{transaction:$('databaseEditRaw').value,customer_id:$('databaseEditCustomer').value.trim()};if(customer&&!body.name)throw Error('Nhập tên khách hàng.');await api('/knowledge/'+(customer?'customers':'patterns')+'/'+encodeURIComponent(selection.key),{method:'PATCH',knowledgeRevision:selection.row._revision,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});closeDatabaseRecord();toast('Đã cập nhật kiến thức.');await Promise.all([loadDatabaseTables(),refresh()])}
async function deleteDatabaseRecord(){const selection=databaseSelected;if(!selection||!$('databaseDeleteConfirm').checked)return;await api('/knowledge/'+(selection.table==='customers'?'customers':selection.table==='payment_templates'?'templates':selection.table==='collection_memberships'?'collections':'patterns')+'/'+encodeURIComponent(selection.key),{method:'DELETE',knowledgeRevision:selection.row._revision});closeDatabaseRecord();toast('Đã xóa kiến thức đã chọn.');await Promise.all([loadDatabaseTables(),refresh()])}
async function openCreateCustomer(){await api('/knowledge/revision');const stamp=knowledgeRevision;databaseReturnFocus=document.activeElement;databaseSelected=null;$('databaseRecordTitle').textContent='Thêm khách hàng';$('databaseRecordBody').innerHTML='<form id="createCustomerForm"><div class="fieldrow"><div><label for="newCustomerId">Mã khách hàng</label><input id="newCustomerId" maxlength="6" pattern="[0-9]{6}" inputmode="numeric" required></div><div><label for="newCustomerName">Tên khách hàng</label><input id="newCustomerName" maxlength="300" required></div></div><label class="check"><input type="checkbox" required><span>Tôi đã kiểm tra mã và tên khách hàng.</span></label><button class="primary" type="submit">Thêm khách hàng</button></form>';$('databaseModal').classList.remove('hidden');$('newCustomerId').focus();$('createCustomerForm').onsubmit=event=>{event.preventDefault();action(event.submitter,async()=>{const result=await post('/knowledge/customers',{id:$('newCustomerId').value.trim(),name:$('newCustomerName').value.trim()},stamp);closeDatabaseRecord();toast('Đã thêm khách hàng '+result.id+'.');databaseCustomerScope=null;databaseTemplateScope=null;databaseOffset=0;$('databaseQuery').value=result.id;$('databaseTable').value='customers';selectTab('database');await stats()})}}
async function openCreatePattern(customerId=''){await api('/knowledge/revision');const stamp=knowledgeRevision;databaseReturnFocus=databaseReturnFocus?.isConnected?databaseReturnFocus:document.activeElement;databaseSelected=null;$('databaseRecordTitle').textContent='Thêm mẫu đã xác nhận';$('databaseRecordBody').innerHTML='<form id="createPatternForm"><div class="fieldrow"><div><label for="newPatternCustomer">Mã khách hàng đã có</label><input id="newPatternCustomer" maxlength="100" list="newPatternCustomerOptions" required value="'+esc(customerId)+'"><datalist id="newPatternCustomerOptions"></datalist></div><div><label for="newPatternDate">Ngày của giao dịch mẫu</label><input id="newPatternDate" type="date"></div></div><label for="newPatternRaw">Nội dung giao dịch mẫu</label><textarea id="newPatternRaw" maxlength="32767" rows="6" required placeholder="Nội dung chuyển khoản"></textarea><div class="fieldrow"><div><label for="newPatternPayer">Ngân hàng / kênh trả tiền</label><input id="newPatternPayer" maxlength="100" required placeholder="Tên ngân hàng hoặc kênh thanh toán"></div><div><label for="newPatternAmount">Số tiền</label><input id="newPatternAmount" type="number" min="0" step="0.01" value="0"></div></div>'+paymentFields('newPatternPayment',{},true)+'<label class="check"><input type="checkbox" required><span>Tôi đã kiểm tra nội dung và khách hàng của mẫu.</span></label><button class="primary" type="submit">Thêm & học mẫu mới</button></form>';$('databaseModal').classList.remove('hidden');$('newPatternRaw').focus();customerAutocomplete('newPatternCustomer','newPatternCustomerOptions');$('createPatternForm').onsubmit=event=>{event.preventDefault();action(event.submitter,async()=>{const customerId=$('newPatternCustomer').value.trim();const result=await post('/knowledge/patterns',{customer_id:customerId,transaction:$('newPatternRaw').value,transaction_date:$('newPatternDate').value,payer:$('newPatternPayer').value.trim(),amount:Number($('newPatternAmount').value||0),...paymentData('newPatternPayment')},stamp);closeDatabaseRecord();toast(result.learned?'Đã bổ sung mẫu mới cho khách hàng.':'Nội dung này đã được học trước đó.');databaseCustomerScope=result.customer_id||customerId;databaseTemplateScope=null;databaseOffset=0;$('databaseQuery').value='';$('databasePaymentMode').value='';$('databaseTable').value='transaction_patterns';selectTab('database');await stats()})}}
for(const id of ['rawFile','knowledgeFile'])$(id).onchange=()=>$(id+'Name').textContent=$(id).files[0]?.name||(id==='rawFile'?'Excel (.xlsx)':'Excel (.xlsx) hoặc CSV (.csv)');
$('batchForm').onsubmit=event=>{event.preventDefault();action(event.submitter,async()=>{if(!$('rawFile').files[0])throw Error('Chọn tệp ngân hàng chưa lọc.');const form=new FormData();form.append('file',$('rawFile').files[0]);form.append('batch_size',$('batchSize').value);await queued(await api('/batch/classify',{method:'POST',body:form}),true)})};
$('knowledgeForm').onsubmit=event=>{event.preventDefault();action(event.submitter,async()=>{if(!$('knowledgeFile').files[0])throw Error('Chọn tệp dữ liệu đã xác nhận.');if(!$('confirmedCheck').checked)throw Error('Xác nhận nhãn khách hàng đã được kiểm tra.');const form=new FormData();form.append('file',$('knowledgeFile').files[0]);form.append('confirmed','true');await queued(await api('/knowledge/import',{method:'POST',body:form}))})};
$('transactionRows').onclick=event=>{const button=event.target.closest('[data-review]');if(button)showReview(rows.get(Number(button.dataset.review)))};
$('transactionRows').onchange=event=>{const input=event.target.closest('[data-select-row]');if(!input)return;const id=Number(input.dataset.selectRow);if(input.checked){if(selectedIds.size>=100){input.checked=false;toast('Có thể xác nhận tối đa 100 giao dịch mỗi lần.',true);return}selectedIds.add(id)}else selectedIds.delete(id);updateSelection()};
$('selectAll').onchange=()=>{for(const row of rows.values())if(canBulkConfirm(row)){if($('selectAll').checked&&selectedIds.size<100)selectedIds.add(row.id);else if(!$('selectAll').checked)selectedIds.delete(row.id)}for(const input of $('transactionRows').querySelectorAll('[data-select-row]'))input.checked=selectedIds.has(Number(input.dataset.selectRow));updateSelection()};
$('clearSelection').onclick=()=>{selectedIds.clear();for(const input of $('transactionRows').querySelectorAll('[data-select-row]'))input.checked=false;updateSelection()};
$('bulkConfirm').onclick=()=>action($('bulkConfirm'),async()=>{const ids=[...selectedIds];if(!ids.length)return;if(!await askConfirmation('Xác nhận & học '+ids.length+' giao dịch','Các dòng đã chọn sẽ được xác nhận theo khách hàng đang đề xuất và bổ sung vào kiến thức. ','Xác nhận & học'))return;const result=await post('/feedback/batch',{transaction_ids:ids});for(const id of result.confirmed)selectedIds.delete(id);toast('Đã xác nhận & học '+result.confirmed.length+' giao dịch.'+(result.errors.length?' Có '+result.errors.length+' dòng cần kiểm tra riêng.':''),result.errors.length>0);await refresh()});
$('jobFilter').onchange=()=>{activeJob=$('jobFilter').value||null;showResults();setExportLinks();refresh().catch(error=>toast(error.message,true))};
for(const id of ['decisionFilter','statusFilter'])$(id).onchange=()=>{showResults();refresh().catch(error=>toast(error.message,true))};
$('resultSearch').onsubmit=event=>{event.preventDefault();showResults();action(event.submitter,refresh)};
$('clearResultsButton').onclick=clearResults;$('refreshButton').onclick=()=>action($('refreshButton'),async()=>{showResults();await jobs();await refresh()});
$('prevButton').onclick=()=>{offset=Math.max(0,offset-20);loadRows().catch(error=>toast(error.message,true))};$('nextButton').onclick=()=>{offset+=20;loadRows().catch(error=>toast(error.message,true))};
$('openTasks').onclick=()=>selectTab('tasks');$('jobsRefresh').onclick=()=>action($('jobsRefresh'),jobs);$('stopImportButton').onclick=()=>action($('stopImportButton'),()=>stopJob(activeImportId));
$('jobs').onclick=event=>{const stop=event.target.closest('[data-stop-job]'),view=event.target.closest('[data-view-job]'),remove=event.target.closest('[data-delete-job]');if(stop){action(stop,()=>stopJob(stop.dataset.stopJob));return}if(view){activeJob=view.dataset.viewJob;$('jobFilter').value=activeJob;showResults();setExportLinks();selectTab('workspace');refresh().catch(error=>toast(error.message,true));return}if(remove)action(remove,async()=>{if(!await askConfirmation('Xóa tệp làm việc?','Kết quả và các xác nhận trong tệp làm việc này sẽ được xóa. Kiến thức đã học vẫn được giữ. ','Xóa tệp làm việc'))return;await api('/jobs/'+encodeURIComponent(remove.dataset.deleteJob),{method:'DELETE'});toast('Đã xóa tệp làm việc. Kiến thức đã học được giữ.');await jobs();if(dbReady)await refresh()})};
$('retryReviews').onclick=()=>action($('retryReviews'),async()=>queued(await post('/reviews/retry',{})));
for(const id of ['addCustomerButton','databaseAddCustomer'])$(id).onclick=()=>action($(id),openCreateCustomer);for(const id of ['addPatternButton','databaseAddPattern'])$(id).onclick=()=>action($(id),()=>openCreatePattern(databaseCustomerScope||''));
$('databaseTable').onchange=()=>{databaseOffset=0;databaseCustomerScope=null;databaseTemplateScope=null;$('databaseQuery').value='';$('databasePaymentMode').value='';loadDatabaseRows().catch(error=>toast(error.message,true))};
for(const button of document.querySelectorAll('[data-table-shortcut]'))button.onclick=()=>{if(!databaseTables.length)return;$('databaseTable').value=button.dataset.tableShortcut;databaseOffset=0;databaseCustomerScope=null;databaseTemplateScope=null;$('databaseQuery').value='';$('databasePaymentMode').value='';loadDatabaseRows().catch(error=>toast(error.message,true))};
$('databaseBulkPayment').onclick=openBulkTemplatePayment;
