$('layoutClose').onclick=closeLayout;$('layoutModal').onclick=event=>{if(event.target===$('layoutModal'))closeLayout()};
document.addEventListener('click',event=>{const link=event.target.closest('[data-layout]');if(!link)return;event.preventDefault();showLayout(link.dataset.layout,link).catch(error=>toast(error.message,true))});
$('databaseSearch').onsubmit=event=>{event.preventDefault();databaseOffset=0;action(event.submitter,loadDatabaseRows)};$('databaseRefresh').onclick=()=>action($('databaseRefresh'),loadDatabaseTables);
$('databasePrev').onclick=()=>{databaseOffset=Math.max(0,databaseOffset-20);loadDatabaseRows().catch(error=>toast(error.message,true))};$('databaseNext').onclick=()=>{databaseOffset+=20;loadDatabaseRows().catch(error=>toast(error.message,true))};$('databaseClearScope').onclick=()=>{databaseCustomerScope=null;databaseTemplateScope=null;databaseOffset=0;loadDatabaseRows().catch(error=>toast(error.message,true))};
$('databaseRows').onclick=event=>{const button=event.target.closest('[data-database-row]');if(button){const meta=databaseMeta(),key=button.dataset.databaseRow;action(button,async()=>{const row=await api('/database/tables/'+encodeURIComponent(meta.name)+'/rows/'+encodeURIComponent(key));if(databaseMeta()?.name===meta.name)showDatabaseRecord(meta,row,button)})}};
const tabs=[...document.querySelectorAll('[data-tab]')];tabs.forEach((button,index)=>{button.onclick=()=>selectTab(button.dataset.tab);button.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(['ArrowRight','ArrowDown'].includes(event.key)?1:-1)+tabs.length)%tabs.length;selectTab(tabs[next].dataset.tab);tabs[next].focus()}});
$('closeModal').onclick=closeReview;$('modalBg').onclick=event=>{if(event.target===$('modalBg'))closeReview()};$('databaseClose').onclick=closeDatabaseRecord;$('databaseModal').onclick=event=>{if(event.target===$('databaseModal'))closeDatabaseRecord()};$('confirmAccept').onclick=()=>finishConfirmation(true);$('confirmCancel').onclick=()=>finishConfirmation(false);
document.onkeydown=event=>{const modal=['confirmModal','layoutModal','databaseModal','modalBg'].map($).find(element=>!element.classList.contains('hidden'));if(!modal)return;if(event.key==='Escape'){if(modal.id==='confirmModal')finishConfirmation(false);else if(modal.id==='layoutModal')closeLayout();else if(modal.id==='databaseModal')closeDatabaseRecord();else closeReview()}if(event.key==='Tab'){const focusable=[...modal.querySelectorAll('button:not(:disabled),input,textarea,select,summary')].filter(element=>element.getClientRects().length),first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}};
(async()=>{try{const response=await fetch('/health'),health=await response.json();dbReady=health.status==='ok';$('health').textContent=dbReady?'Sẵn sàng':'Chưa sẵn sàng';$('health').className='health '+(dbReady?'ok':'setup_required');$('setup').classList.toggle('hidden',dbReady)}catch{$('health').textContent='Kết nối gián đoạn';$('setup').classList.remove('hidden')}document.querySelectorAll('.needs-db').forEach(button=>button.disabled=!dbReady);try{const active=await jobs();if(dbReady)await refresh();if(active)pollJobs()}catch(error){toast(error.message,true)}})();

